#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "ompvv.h"
#include <math.h>

# define N 1024

int errors;

int test_full_loop_unroll() {
        int arr[N];
        int parallel_arr[N];
        int sum = 0;
        int parallel_sum = 0;

        // sequential loop
        for (int i = 0; i < N; i++) {
                arr[i] = i;
                sum += arr[i];
        }

        // omp unroll full loop
# pragma omp unroll full
        for (int i = 0; i < N; i++) {
                parallel_arr[i] = i;
