#include <assert.h>
#include <stdlib.h>
#include "ompvv.h"

#define N 10
int errors = 0;

void fun();
void host_function();

#pragma omp declare target to(fun) device_type(any)

#pragma omp declare target
int a[N], b[N], c[N];
int i = 0, dev=-9;
#pragma omp end declare target

#pragma omp declare variant(host_function) match(device={kind(host)})
