// the host.
//
////===--------------------------------------------------------------------------------------------===//

#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "ompvv.h"

#define N 1024

int errors;

int test_close_modifier() {

  int i;
  int scalar = 19;
  int a[N];

  struct {
    int var;
    int b[N];
  } member;

  member.var = 1;

  for (i = 0; i < N; i++) {
    a[i] = i;
    member.b[i] = i;
  }

#pragma omp target map (close, tofrom: scalar, a, member)
  {
    scalar += 25;
    member.var += 16;

    for (i = 0; i < N; i++) {
      a[i] += i*2;
      member.b[i] += i*2;
    }
  }

  for (i = 0; i < N; i++) {
    OMPVV_TEST_AND_SET(errors, a[i] != i*3);
    OMPVV_TEST_AND_SET(errors, member.b[i] != i*3);
  }

  OMPVV_TEST_AND_SET(errors, scalar != 44);
  OMPVV_TEST_AND_SET(errors, member.var != 17);

  return errors;
}

