  for (int i = 0; i < N; i++) {
    c[i] = a[i] + b[i];
  }
#pragma omp taskwait
  for (int i = 0; i < N; i++) {
    OMPVV_TEST_AND_SET_VERBOSE(errors, c[i] != a[i] + b[i]);
  }
  free(a);
  free(b);
  free(c);
  OMPVV_REPORT_AND_RETURN(errors);
}

