                x[i] = i;
                y[i] = i;
        }

        OMPVV_TEST_OFFLOADING;

        #pragma omp target map(tofrom: x,y)
        {
                #pragma omp parallel
                {
                   #pragma omp single
                   #pragma omp taskloop simd order(reproducible:concurrent)
                      for (int i = 0; i < N; i++) {
                         x[i] = x[i] + 2;
                      }

                   #pragma omp single
                   #pragma omp taskloop simd order(reproducible:concurrent)
                      for (int i = 0; i < N; i++) {
                        y[i] = x[i] + 2;
