// only a host version of the procedure is made available. The "enter" clause was introduced
// to replace the to clause in 5.2.
//
//===-------------------------------------------------------------------------------===//

#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "ompvv.h"

#define N 1024
